// Some portions generated by Codex
package org.eclipse.rdf4j.http.client;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import org.junit.jupiter.api.Test;

class QueryRequestContextTest {

	@Test
	void activationNormalizesNestsAndRestoresRequestIds() {
		assertThat(QueryRequestContext.getQueryRequestId()).isNull();

		try (QueryRequestContext.Activation outer = QueryRequestContext.activate(" outer ")) {
			assertThat(QueryRequestContext.getQueryRequestId()).isEqualTo("outer");
			try (QueryRequestContext.Activation inner = QueryRequestContext.activate("inner")) {
				assertThat(QueryRequestContext.getQueryRequestId()).isEqualTo("inner");
			}
			assertThat(QueryRequestContext.getQueryRequestId()).isEqualTo("outer");
		}

		assertThat(QueryRequestContext.getQueryRequestId()).isNull();
	}

	@Test
	void activationRejectsMissingRequestIds() {
		assertThatThrownBy(() -> QueryRequestContext.activate(null))
				.isInstanceOf(NullPointerException.class)
				.hasMessage("Query request id was null");
		assertThatThrownBy(() -> QueryRequestContext.activate("  "))
				.isInstanceOf(IllegalArgumentException.class)
				.hasMessage("Query request id was blank");
	}
}
